-- Disposable replay database only. No provider or external runner dispatch.
BEGIN;
DELETE FROM public.app_settings WHERE key IN ('runner_url','runner_token');
CREATE FUNCTION pg_temp.assert(ok boolean,message text) RETURNS void LANGUAGE plpgsql AS $$ BEGIN IF ok IS DISTINCT FROM true THEN RAISE EXCEPTION '%',message; END IF; END $$;
CREATE FUNCTION pg_temp.denied(q text) RETURNS void LANGUAGE plpgsql AS $$ DECLARE failed boolean:=false; BEGIN BEGIN EXECUTE q; EXCEPTION WHEN OTHERS THEN failed:=true; END; IF NOT failed THEN RAISE EXCEPTION 'Expected rejection: %',q; END IF; END $$;
SELECT pg_temp.assert((SELECT count(*) FROM public.generator_prompt_default)=1,'Exactly one default');
SELECT pg_temp.assert((SELECT builtin_version='v1' FROM public.generator_prompt_versions p JOIN public.generator_prompt_default d ON p.id=d.prompt_id),'V1 remains default');
SELECT pg_temp.assert((SELECT encode(extensions.digest(content,'sha256'),'hex')=digest FROM public.generator_prompt_versions WHERE family='master_v1'),'Seed exact digest');
SELECT pg_temp.assert(NOT has_table_privilege('authenticated','public.generator_prompt_versions','SELECT,INSERT,UPDATE,DELETE'),'No direct authenticated content access');
SELECT pg_temp.assert(NOT has_table_privilege('service_role','public.generator_prompt_versions','UPDATE,DELETE'),'No service mutation bypass');
SELECT pg_temp.assert(NOT has_function_privilege('anon','public.generator_prompt_catalog()','EXECUTE'),'Anonymous RPC denied');
SELECT pg_temp.assert(NOT has_function_privilege('authenticated','public.generator_prompt_for_job_internal(uuid,uuid)','EXECUTE'),'Worker RPC private');
SELECT pg_temp.assert(has_function_privilege('service_role','public.generator_prompt_for_job_internal(uuid,uuid)','EXECUTE'),'Worker RPC service grant');
SELECT pg_temp.assert((SELECT bool_and(relrowsecurity) FROM pg_class WHERE oid IN ('public.generator_prompt_versions'::regclass,'public.generator_prompt_default'::regclass,'public.generator_prompt_audit'::regclass)),'All catalog tables require RLS');
INSERT INTO auth.users(id,email) VALUES ('af510000-0000-4000-8000-000000000001','prompt-admin@example.invalid'),('af510000-0000-4000-8000-000000000002','prompt-user@example.invalid'),('af510000-0000-4000-8000-000000000003','prompt-banned@example.invalid');
INSERT INTO public.user_roles(user_id,role,moderation_status) VALUES ('af510000-0000-4000-8000-000000000001','super_admin','active');
INSERT INTO public.profile_private(user_id,is_banned) VALUES ('af510000-0000-4000-8000-000000000001',false),('af510000-0000-4000-8000-000000000002',false),('af510000-0000-4000-8000-000000000003',false) ON CONFLICT(user_id) DO UPDATE SET is_banned=excluded.is_banned;
UPDATE public.feature_access_policies SET access_mode='everyone' WHERE feature_key='ai_generator';
SELECT set_config('request.jwt.claim.sub','af510000-0000-4000-8000-000000000002',true);
SET LOCAL ROLE authenticated;
SELECT pg_temp.denied('SELECT public.generator_prompt_catalog()');
SELECT pg_temp.denied('SELECT public.generator_prompt_read(gen_random_uuid())');
SELECT pg_temp.denied('SELECT public.generator_prompt_import(''bad'',''not a template'')');
SELECT public.start_generation_job('af520000-0000-4000-8000-000000000001','{"theme":"Offline only","generationModel":"offline","promptVersion":"v1"}');
RESET ROLE;
SELECT pg_temp.assert((SELECT input_payload->>'promptVersion'='v1' AND prompt_catalog_id IS NOT NULL FROM public.ai_generation_jobs WHERE idempotency_key='af520000-0000-4000-8000-000000000001'),'Ordinary default binding');
UPDATE public.ai_generation_jobs SET status='completed',result='{"title":"x","tags":"y","lyrics":"z","note":"n"}' WHERE idempotency_key='af520000-0000-4000-8000-000000000001';
CREATE TEMP TABLE registry_fixture AS SELECT id AS candidate FROM public.generator_prompt_versions WHERE family='master_v1';
GRANT SELECT ON registry_fixture TO authenticated;
SET LOCAL ROLE authenticated;
SELECT pg_temp.denied(format('SELECT public.start_generation_job(gen_random_uuid(),%L::jsonb)',jsonb_build_object('promptVersion','registry','registryPromptId',(SELECT candidate FROM registry_fixture),'inputSnapshot',jsonb_build_object('generatorMode','advanced'))::text));
RESET ROLE;
SELECT set_config('request.jwt.claim.sub','af510000-0000-4000-8000-000000000001',true);
CREATE TEMP TABLE registry_ids AS SELECT prompt_id AS original FROM public.generator_prompt_default;
GRANT SELECT ON registry_ids TO authenticated;
SET LOCAL ROLE authenticated;
SELECT pg_temp.assert(jsonb_array_length(public.generator_prompt_catalog())=6,'Admin list without bodies');
SELECT pg_temp.assert(NOT (public.generator_prompt_catalog()->0 ? 'content'),'Catalog metadata never contains body');
SELECT public.generator_prompt_mutate((SELECT candidate FROM registry_fixture),'default',(SELECT original FROM registry_ids));
SELECT pg_temp.denied(format('SELECT public.generator_prompt_mutate(%L,''archive'',%L)',(SELECT candidate FROM registry_fixture),(SELECT candidate FROM registry_fixture)));
SELECT public.start_generation_job('af520000-0000-4000-8000-000000000002','{"theme":"Offline only","generationModel":"offline","promptVersion":"default"}');
RESET ROLE;
SELECT pg_temp.assert((SELECT input_payload->>'promptVersion'='registry' FROM public.ai_generation_jobs WHERE idempotency_key='af520000-0000-4000-8000-000000000002'),'Default routes template');
SET LOCAL ROLE authenticated;
SELECT public.generator_prompt_mutate((SELECT original FROM registry_ids),'default',(SELECT candidate FROM registry_fixture));
SELECT public.generator_prompt_mutate((SELECT candidate FROM registry_fixture),'archive',(SELECT original FROM registry_ids));
SELECT pg_temp.denied(format('SELECT public.generator_prompt_mutate(%L,''delete'',%L)',(SELECT candidate FROM registry_fixture),(SELECT original FROM registry_ids)));
RESET ROLE;
SELECT pg_temp.assert((SELECT input_payload#>>'{promptBinding,id}'=(SELECT candidate::text FROM registry_fixture) FROM public.ai_generation_jobs WHERE idempotency_key='af520000-0000-4000-8000-000000000002'),'Switch/archive preserves pinned job');
SELECT pg_temp.denied('UPDATE public.ai_generation_jobs SET input_payload=input_payload-''promptBinding'' WHERE idempotency_key=''af520000-0000-4000-8000-000000000002''');
SELECT pg_temp.denied('UPDATE public.generator_prompt_versions SET content=content||''changed'' WHERE family=''master_v1''');
SELECT pg_temp.assert((SELECT public.generator_prompt_for_job_internal((SELECT id FROM public.ai_generation_jobs WHERE idempotency_key='af520000-0000-4000-8000-000000000002'),'af510000-0000-4000-8000-000000000001')->>'content' IS NOT NULL),'Archived pinned content recoverable');
SELECT pg_temp.assert(public.generator_prompt_for_job_internal((SELECT id FROM public.ai_generation_jobs WHERE idempotency_key='af520000-0000-4000-8000-000000000002'),'af510000-0000-4000-8000-000000000002') IS NULL,'Worker owner isolation');
SET LOCAL ROLE authenticated;
SELECT pg_temp.denied(format('SELECT public.generator_prompt_mutate(%L,''default'',%L)',(SELECT candidate FROM registry_fixture),(SELECT candidate FROM registry_fixture)));
SELECT public.generator_prompt_mutate((SELECT candidate FROM registry_fixture),'restore',(SELECT original FROM registry_ids));
RESET ROLE;
-- No user songs or existing jobs are removed by any catalog operation.
SELECT pg_temp.assert((SELECT count(*) FROM public.ai_generation_jobs WHERE idempotency_key IN ('af520000-0000-4000-8000-000000000001','af520000-0000-4000-8000-000000000002'))=2,'Job history retained');
-- Import/delete/restore validation through the real authenticated SQL API.
SET LOCAL ROLE authenticated;
SELECT pg_temp.denied('SELECT public.generator_prompt_import(''Invalid contract'',''{{CORE_IDEA}} {{GENRES}} {{MOOD}} {{LANGUAGE}} {{TARGET_PLATFORM}} {{SONG_STRUCTURE}} {{PRODUCTION_STYLE}} {{ADDITIONAL_INSTRUCTIONS}} {{SONG_BLUEPRINT}}'')');
RESET ROLE;
CREATE TEMP TABLE new_prompt AS SELECT public.generator_prompt_import('Temporary unreferenced version',(SELECT content FROM public.generator_prompt_versions WHERE family='master_v1')) AS id;
GRANT SELECT ON new_prompt TO authenticated;
SET LOCAL ROLE authenticated;
SELECT public.generator_prompt_mutate((SELECT id FROM new_prompt),'delete',(SELECT original FROM registry_ids));
RESET ROLE;
SELECT pg_temp.assert(NOT EXISTS(SELECT 1 FROM public.generator_prompt_versions WHERE id=(SELECT id FROM new_prompt)),'Unreferenced unused import deleted');
SELECT pg_temp.assert(EXISTS(SELECT 1 FROM public.generator_prompt_audit WHERE prompt_id=(SELECT id FROM new_prompt) AND action='delete'),'Deletion audit retains digest without body');
-- A production default is available to an ordinary account, without exposing
-- the body or granting experimental selection to that account.
SET LOCAL ROLE authenticated;
SELECT public.generator_prompt_mutate((SELECT candidate FROM registry_fixture),'default',(SELECT original FROM registry_ids));
RESET ROLE;
SELECT set_config('request.jwt.claim.sub','af510000-0000-4000-8000-000000000002',true);
SET LOCAL ROLE authenticated;
SELECT public.start_generation_job('af520000-0000-4000-8000-000000000003','{"theme":"Offline default","promptVersion":"v1","generationModel":"offline"}');
RESET ROLE;
SELECT pg_temp.assert((SELECT input_payload->>'promptVersion'='registry' AND (input_payload#>>'{promptBinding,experimental}')::boolean=false FROM public.ai_generation_jobs WHERE idempotency_key='af520000-0000-4000-8000-000000000003'),'Ordinary users cannot choose weaker legacy prompt');
SELECT pg_temp.assert(NOT EXISTS(SELECT 1 FROM public.ai_generation_jobs WHERE input_payload::text LIKE '%## 19%'),'No template body in jobs');
-- Fresh Super Admin authority is required at every catalog operation.
UPDATE public.ai_generation_jobs SET status='completed' WHERE idempotency_key='af520000-0000-4000-8000-000000000002';
SELECT set_config('request.jwt.claim.sub','af510000-0000-4000-8000-000000000001',true);
SET LOCAL ROLE authenticated;
SELECT public.generator_prompt_mutate((SELECT original FROM registry_ids),'default',(SELECT candidate FROM registry_fixture));
SELECT public.start_generation_job('af520000-0000-4000-8000-000000000004',jsonb_build_object('promptVersion','registry','registryPromptId',(SELECT candidate FROM registry_fixture),'generationModel','offline','inputSnapshot',jsonb_build_object('generatorMode','advanced')));
RESET ROLE;
CREATE TEMP TABLE experimental_job AS SELECT id FROM public.ai_generation_jobs WHERE idempotency_key='af520000-0000-4000-8000-000000000004';
GRANT SELECT ON experimental_job TO service_role;
SELECT set_config('request.jwt.claim.sub','',true);
SET LOCAL ROLE service_role;
SELECT pg_temp.assert(public.generator_prompt_for_job_internal((SELECT id FROM experimental_job),'af510000-0000-4000-8000-000000000001')->>'content' IS NOT NULL,'Service worker without user JWT can resolve authorized experimental job');
SELECT pg_temp.assert(public.generator_prompt_for_job_internal((SELECT id FROM experimental_job),'af510000-0000-4000-8000-000000000002') IS NULL,'Service worker owner mismatch rejected');
RESET ROLE;
UPDATE public.user_roles SET role='user' WHERE user_id='af510000-0000-4000-8000-000000000001';
SET LOCAL ROLE service_role;
SELECT pg_temp.assert(public.generator_prompt_for_job_internal((SELECT id FROM experimental_job),'af510000-0000-4000-8000-000000000001') IS NULL,'Revoked experimental privilege is rechecked without JWT');
RESET ROLE;
SELECT set_config('request.jwt.claim.sub','af510000-0000-4000-8000-000000000001',true);
SET LOCAL ROLE authenticated;
SELECT pg_temp.denied('SELECT public.generator_prompt_catalog()');
ROLLBACK;
